let originalText = "";
let firmaOrigen = "Unknown";
let idGitlab = "";

// 1. Bulletproof Data Retrieval (Fallback Chain)
if ($json.texto_para_ia) {
    originalText = $json.texto_para_ia;
    firmaOrigen = $json.firma_origen;
    idGitlab = $json.id_gitlab || "";
} else {
    try {
        const loopData = $('Loop Over Items').first().json;
        if (loopData && loopData.texto_para_ia) {
            originalText = loopData.texto_para_ia;
            firmaOrigen = loopData.firma_origen;
            idGitlab = loopData.id_gitlab || "";
        } else {
            throw new Error("No data in Loop");
        }
    } catch (errorLoop) {
        try {
            const slackData = $('Format Slack Data').first().json;
            originalText = slackData.texto_para_ia || "";
            firmaOrigen = slackData.firma_origen || "Unknown";
            idGitlab = slackData.id_gitlab || "";
        } catch (errorSlack) {
            try {
                const webhookData = $('Format Webhook Data').first().json;
                originalText = webhookData.texto_para_ia || "";
                firmaOrigen = webhookData.firma_origen || "Universal Webhook Pipeline";
                idGitlab = webhookData.id_gitlab || "";
            } catch (errorWebhook) {
                originalText = "";
            }
        }
    }
}

// 2. Safely Mask Data (Optimized Regex)
const ipRegex = /\b(?:\d{1,3}\.){3}\d{1,3}\b/g;
let sanitizedText = originalText.replace(ipRegex, '[IP_REDACTED]');

const emailRegex = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g;
sanitizedText = sanitizedText.replace(emailRegex, '[EMAIL_REDACTED]');

const urlRegex = /https?:\/\/[^\s]+/g;
sanitizedText = sanitizedText.replace(urlRegex, '[URL_REDACTED]');

const slackUserRegex = /<@U[A-Z0-9]+>/g;
sanitizedText = sanitizedText.replace(slackUserRegex, '[USER_REDACTED]');

const domainRegex = /\b[a-zA-Z0-9.-]+\.(?:com|net|org|local|internal|edu|gov)\b/gi;
sanitizedText = sanitizedText.replace(domainRegex, '[DOMAIN_REDACTED]');

// 3. Attach and return for the AI Agent
$json.sanitized_text = sanitizedText;
$json.original_text = originalText;
$json.firma_origen = firmaOrigen;
$json.id_gitlab = idGitlab; // Pasamos el ID tal cual viene del origen

return $json;

const agentResponse = $input.first().json.output || "";

// NEW: The "Bypass" Check
// If the Structured Output Parser did its job perfectly, agentResponse is already an object!
if (typeof agentResponse === 'object' && agentResponse !== null) {
    return { output: agentResponse };
}

// 1. Function to deeply clean and extract JSON from messy AI outputs (String fallback)
function extractAndCleanJSON(rawText) {
    // Safety check: ensure it is actually a string before manipulating
    if (typeof rawText !== 'string') {
        return null; 
    }

    // Strip markdown code blocks if the AI added them
    let cleanedText = rawText.replace(/```json/gi, '').replace(/```/g, '');

    // Find the absolute boundaries of the JSON object
    const startIndex = cleanedText.indexOf('{');
    const endIndex = cleanedText.lastIndexOf('}');

    if (startIndex === -1 || endIndex === -1) {
        return null; // No JSON object boundaries found
    }

    // Extract just the JSON payload
    let jsonString = cleanedText.substring(startIndex, endIndex + 1);

    // 2. The Cleaner: Scrub common stringification artifacts from local LLMs
    jsonString = jsonString.replace(/\\n/g, ' ');
    jsonString = jsonString.replace(/\\t/g, ' ');
    jsonString = jsonString.replace(/\\"/g, '"');
    jsonString = jsonString.replace(/[\u0000-\u0019]+/g, "");

    // 3. Attempt to parse the sanitized string
    try {
        return JSON.parse(jsonString);
    } catch (error) {
        console.log("JSON Parse Error after cleaning:", error.message);
        return null;
    }
}

// Execute the cleaner ONLY if it's a messy string
const structuredData = extractAndCleanJSON(agentResponse);

// If parsing was successful, return the clean object
if (structuredData) {
    return { output: structuredData };
}

// 4. Fallback Ticket (Strictly in English)
// Safely convert agentResponse for the ticket description just in case
const rawCapture = typeof agentResponse === 'string' ? agentResponse : JSON.stringify(agentResponse);

return [{
    json: {
        output: {
            title: "Manual Triage Required: AI Agent Failure",
            description: "The AI agent failed to return a valid JSON response. It likely encountered a strict API boundary or generated malformed formatting that could not be sanitized.\n\n**Raw captured response:**\n" + rawCapture,
            cwe_id: "PENDING-MANUAL-REVIEW",
            cvss_score: 0,
            related_cves: [{
                cve_id: "PENDING-MANUAL-REVIEW",
                confidence_score: 0,
                context: "Parsing algorithm failed to extract valid JSON.",
                epss_badge: ""
            }],
            remediation: "Review the raw payload manually to determine the vulnerability context."
        }
    }
}];

