// Función nativa para generar el hash
function createSimpleHash(str) {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
        const char = str.charCodeAt(i);
        hash = ((hash << 5) - hash) + char;
        hash = hash & hash;
    }
    return Math.abs(hash).toString(16);
}

for (const item of $input.all()) {
    let textoCombinado = "";

    // Extraemos todas las columnas (claves) dinámicamente de esta fila
    const columnasOriginales = Object.keys(item.json);

    // 1. Recorremos cada columna y montamos un texto estructurado para la IA
    for (const columna of columnasOriginales) {
        const valor = item.json[columna];
        if (valor) { // Solo añadimos si la celda no está vacía
            textoCombinado += `${columna.toUpperCase()}: ${valor}\n`;
        }
    }

    // 2. Asignamos el texto gigante a nuestra variable estándar
    item.json.texto_para_ia = textoCombinado.trim();

    // 3. Generamos el Hash único basado en TODA la información de la fila
    const hash = "REF-" + createSimpleHash(item.json.texto_para_ia);

    item.json.id_gitlab = hash;
    item.json.firma_origen = 'DevSecOps Batch Portal';

    // 4. LIMPIEZA DINÁMICA: Borramos las columnas originales para no ensuciar el JSON
    for (const columna of columnasOriginales) {
        delete item.json[columna];
    }
}

return $input.all();

// Función nativa para generar el hash
function createSimpleHash(str) {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
        const char = str.charCodeAt(i);
        hash = ((hash << 5) - hash) + char;
        hash = hash & hash;
    }
    return Math.abs(hash).toString(16);
}

for (const item of $input.all()) {
    const slackData = $('Get the history of a channel').first().json;

    item.json.texto_para_ia = slackData.text;

    // Generamos el ID aquí, ANTES de que empiece la búsqueda
    item.json.id_gitlab = "REF-" + createSimpleHash(slackData.text);
    item.json.firma_origen = 'Slack ChatOps';
}
return $input.all();

// Función nativa para generar el hash sin usar módulos externos
function createSimpleHash(str) {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
        const char = str.charCodeAt(i);
        hash = ((hash << 5) - hash) + char;
        hash = hash & hash;
    }
    return Math.abs(hash).toString(16);
}

const webhookBody = $input.item.json.body;
const rawJsonString = JSON.stringify(webhookBody, null, 2);
const texto_para_ia = "RAW_WEBHOOK_PAYLOAD:\n" + rawJsonString;

// Generamos el ID único basado en el contenido exacto del Webhook
const generatedId = "REF-" + createSimpleHash(texto_para_ia);

return [{
    json: {
        id_gitlab: generatedId,
        texto_para_ia: texto_para_ia,
        firma_origen: "Universal Webhook Pipeline"
    }
}];

const data = $input.item.json;

// Verificamos que existan CVEs
if (data.output && data.output.related_cves && data.output.related_cves.length > 0) {

    // Iteramos sobre CADA CVE detectado
    for (const cveItem of data.output.related_cves) {

        // Buscamos si tenemos datos del FIRST API para este ID específico
        // Asumimos que 'data.data' es el array que viene del nodo de la API
        const epssMatch = data.data ? data.data.find(e => e.cve === cveItem.cve_id) : null;

        if (epssMatch) {
            const percentage = (parseFloat(epssMatch.epss) * 100).toFixed(2) + "%";
            cveItem.epss_badge = ` *([EPSS](https://www.first.org/epss/model): **${percentage}** prob.)*`;
        } else {
            cveItem.epss_badge = " *([EPSS](https://www.first.org/epss/model): N/A)*";
        }
    }
}

return [{ json: data }];

